import math


class IndependentSlotsStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.SetWarmUp(101, Resolution.Daily)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        spy_bar_present = data.Bars.ContainsKey(self.spy)
        aapl_bar_present = data.Bars.ContainsKey(self.aapl)

        if spy_bar_present:
            spy_close = data.Bars[self.spy].Close
            self.spy_sma.Update(IndicatorDataPoint(data.Time, spy_close))
        else:
            spy_close = None

        if aapl_bar_present:
            aapl_close = data.Bars[self.aapl].Close
            self.aapl_rsi.Update(IndicatorDataPoint(data.Time, aapl_close))

            if self.previous_aapl_close is not None and aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        else:
            aapl_close = None

        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values())

        if (
            all_bars_present
            and not self.IsWarmingUp
            and self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            self.strategy_a_lot = int(self.Portfolio[self.spy].Quantity)
            self.strategy_b_lot = int(self.Portfolio[self.aapl].Quantity)

            current_spy_sma = self.spy_sma.Current.Value

            # Sells before buys.
            if (
                self.strategy_a_lot > 0
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_close < current_spy_sma
            ):
                self.MarketOrder(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

            if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

            if (
                self.strategy_a_lot == 0
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_close > current_spy_sma
            ):
                quantity = int(math.floor(
                    float(self.Portfolio.TotalPortfolioValue * 0.40 / spy_close)
                ))
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_lot = quantity

            if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(math.floor(float(20000 / aapl_close)))
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.strategy_b_lot = quantity

        if spy_bar_present:
            if self.spy_sma.IsReady:
                self.previous_spy_close = spy_close
                self.previous_spy_sma = self.spy_sma.Current.Value

        if aapl_bar_present:
            self.previous_aapl_close = aapl_close
