        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.spy_sma_values = RollingWindow[float](2)
        self.aapl_closes = RollingWindow[float](2)

        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = data.Bars

        # Market-state quantities continue updating whenever their own data exists.
        if bars.ContainsKey(self.spy):
            spy_close = float(bars[self.spy].Close)
            self.spy_sma.Update(self.Time, spy_close)
            if self.spy_sma.IsReady:
                self.spy_sma_values.Add(float(self.spy_sma.Current.Value))

        if bars.ContainsKey(self.aapl):
            aapl_close = float(bars[self.aapl].Close)

            if self.aapl_closes.Count > 0:
                if aapl_close < self.aapl_closes[0]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_closes.Add(aapl_close)
            self.aapl_rsi.Update(self.Time, aapl_close)

        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not (
            self.spy_sma.IsReady
            and self.spy_sma_values.Count >= 2
            and self.aapl_rsi.IsReady
            and self.aapl_closes.Count >= 2
        ):
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        spy_sma_today = self.spy_sma_values[0]
        spy_sma_yesterday = self.spy_sma_values[1]
        spy_close_yesterday = float(bars[self.spy].Close)  # replaced below from price history

