from AlgorithmImports import *
from collections import deque


class IndependentSlotsStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.close_windows = {ticker: deque(maxlen=101) for ticker in self.symbols}
        self.previous_closes = {ticker: None for ticker in self.symbols}
        self.red_streaks = {ticker: 0 for ticker in self.symbols}

        self.rsi_previous_close = None
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_delta_count = 0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol in data.Bars:
                bars[ticker] = data.Bars[symbol]

        # Keep market-state calculations current for every ticker with a bar.
        for ticker, bar in bars.items():
            close = float(bar.Close)
            previous_close = self.previous_closes[ticker]

            if previous_close is not None:
                if close < previous_close:
                    self.red_streaks[ticker] += 1
                else:
                    self.red_streaks[ticker] = 0

            self.close_windows[ticker].append(close)
            self.previous_closes[ticker] = close

        if "AAPL" in bars:
            self._update_aapl_rsi(float(bars["AAPL"].Close))

        # No rule evaluation unless every subscribed ticker has today's bar.
        if len(bars) != len(self.symbols):
            return

        # Do not trade until all rule inputs are fully formed.
        if len(self.close_windows["SPY"]) < 101 or self.aapl_rsi is None:
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        spy_closes = list(self.close_windows["SPY"])
        previous_sma100 = sum(spy_closes[:100]) / 100.0
        current_sma100 = sum(spy_closes[1:]) / 100.0

        spy_crosses_above = (
            spy_closes[-2] <= previous_sma100 and
            spy_close > current_sma100
        )
        spy_crosses_below = (
            spy_closes[-2] >= previous_sma100 and
            spy_close < current_sma100
        )

        # Evaluate sells before buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            shares = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.red_streaks["AAPL"] >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_lot = shares

    def _update_aapl_rsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        self.rsi_previous_close = close

        if self.rsi_delta_count < 14:
            self.rsi_gain_sum += gain
            self.rsi_loss_sum += loss
            self.rsi_delta_count += 1

            if self.rsi_delta_count == 14:
                self.rsi_average_gain = self.rsi_gain_sum / 14.0
                self.rsi_average_loss = self.rsi_loss_sum / 14.0
                self.aapl_rsi = self._rsi_value()
            return

        self.rsi_average_gain = ((self.rsi_average_gain * 13.0) + gain) / 14.0
        self.rsi_average_loss = ((self.rsi_average_loss * 13.0) + loss) / 14.0
        self.aapl_rsi = self._rsi_value()

    def _rsi_value(self):
        if self.rsi_average_loss == 0:
            return 100.0
        relative_strength = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))
